mapper.select:
WITH people AS (
  SELECT c.dev_id FROM cst.mth_cst c WHERE c.cst_ym=#{month}
  UNION SELECT a.dev_id FROM asgn.asgn a WHERE 
  UNION SELECT e.dev_id FROM cst.drct_expns e WHERE e.expns_ym=#{month} AND e.dev_id IS NOT NULL
)
SELECT d.dev_id,coalesce(c.emp_se_cd,d.emp_se_cd) AS emp_se_cd,
  coalesce(c.duty_se_cd,d.duty_se_cd) AS duty_se_cd,c.indv_lbr_cst_amt
FROM people x JOIN mst.dev d ON d.dev_id=x.dev_id
LEFT JOIN cst.mth_cst c ON c.dev_id=d.dev_id AND c.cst_ym=#{month}
ORDER BY d.dev_id

SELECT x.month FROM (
  SELECT m.work_ym AS month FROM asgn.asgn a JOIN asgn.asgn_mth m ON m.asgn_id=a.asgn_id
    WHERE a.prj_id=#{projectId} AND a.asgn_stts_cd!='CANCELLED'
  UNION SELECT e.expns_ym AS month FROM cst.drct_expns e WHERE e.prj_id=#{projectId}
  UNION SELECT c.cst_ym AS month FROM cst.cst_aloc c WHERE c.prj_id=#{projectId}
) x WHERE x.month <=#{throughMonth} ORDER BY x.month
